import { useCallback, useMemo, useState } from 'react';

import { useExportPdf } from 'hooks';
import { PDF_DEFAULT_CONFIG } from 'pages/pillars/ValueCreation/VolumePages/constants/pdfConfig';
import {
  useRegisterLoading,
  useVolumePagesKpi,
} from 'pages/pillars/ValueCreation/VolumePages/contexts';
import { useVolumePageExportScopeName } from 'pages/pillars/ValueCreation/VolumePages/hooks/useVolumePageExportScopeName';
import { UseExportSummaryPageHeaderProps } from 'pages/pillars/ValueCreation/VolumePages/tabs/Summary/components/ExportSummaryPageHeader/types';
import { pageSections } from 'pages/pillars/ValueCreation/VolumePages/tabs/Summary/constants/sections';

export const useExportSummaryPageHeader = ({
  monthYear,
}: UseExportSummaryPageHeaderProps) => {
  const { kpiName } = useVolumePagesKpi();
  const productScopeName = useVolumePageExportScopeName();
  const [isExporting, setIsExporting] = useState(false);
  useRegisterLoading('summary-export', isExporting);

  const fileName = useMemo(() => {
    const baseFileName = `Value Creation - Summary ${kpiName} - ${monthYear.toUpperCase()}`;

    return `Volume Page - ${productScopeName} - ${baseFileName}`;
  }, [kpiName, monthYear, productScopeName]);

  const pdfConfig = useMemo(
    () => ({ ...PDF_DEFAULT_CONFIG, filename: fileName }),
    [fileName],
  );

  const { onExport } = useExportPdf(pdfConfig);

  const handlePDFExport = useCallback(async () => {
    setIsExporting(true);
    try {
      await onExport(
        Object.values(pageSections)
          .map((section) =>
            document.querySelector(`[data-page-name=${section}]`),
          )
          .filter(Boolean) as HTMLElement[],
      );
    } finally {
      setIsExporting(false);
    }
  }, [onExport]);

  return { handlePDFExport };
};
